// =========================================================================
// PRESET SHADER: Mount Zoomington 3D
// Author: chronos
// Original Link: https://www.shadertoy.com/view/7cBSRW
// License: Creative Commons Attribution-NonCommercial-ShareAlike 3.0 Unported
// =========================================================================
// This shader implements a 3D raymarched logarithmic grid study.
// Integrated into SurfaceExplorer. Distributed under CC BY-NC-SA 3.0 terms.
// =========================================================================

// Yeah... The artistry leaves something to be desired... don't @ me :P
// This is more of an exploration of a technique.

float map(vec3 p)
{
    float sdf = p.y;

    vec2 q = p.xz;
    float r = length(q);
    float a = atan(q.y, q.x);

    float f = 0.;
    for(float j = 0.125; j < 1.; j+=j)
    {
        // The reason to do the fract here is just to avoid numerical issues.
        q = vec2(2. * PI *(fract(iTime*.25)*4. + log2(r)), a * 4.);
        vec2 wave = cos(2. * q*j);
        f += dot(wave, wave.yx) / j * r;
    }
    //    float f = sin(2. * PI * (iTime + log(r)) + a);

    float h = .5+.5*f;
    sdf += h*.1;
    return sdf;
}

float getLaplacian(vec3 p) {
    float e = .05;
    float d = map(p);
    float dx = map(p + vec3(e, 0, 0)) + map(p - vec3(e, 0, 0));
    float dy = map(p + vec3(0, e, 0)) + map(p - vec3(0, e, 0));
    float dz = map(p + vec3(0, 0, e)) + map(p - vec3(0, 0, e));
    return (dx + dy + dz - 6.0 * d) / (e * e);
}    

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (2. * fragCoord - iResolution.xy)/iResolution.y;

    float focal = 2.;
    vec3 ro = vec3(0,2.35,3);
    vec3 rd = normalize(vec3(uv, -focal));

    float tilt = .5;
    float c = cos(tilt), s = sin(tilt);
    mat2 R = mat2(c,s,-s,c);
    rd.yz *= R;

    c = cos(iTime*.2), s = sin(iTime*.2);
    R = mat2(c,s,-s,c);
    ro.xz *= R;
    rd.xz *= R;

    vec3 color = vec3(0);

    float t = 0.;
    vec3 p;
    for(float i = 0.; i < 80. && t < 1e3; i++)
    {
        p = rd * t + ro;

        float sdf = map(p);

        float dt = (sdf)*.25;
        t += dt;
        if(sdf < 1e-3) break;
    }

    vec3 n; // normal tetrahedron technique: https://iquilezles.org/articles/normalsSDF/
    {
    const float h = 0.005;
    const vec2 k = vec2(1,-1);
    n = normalize(
               k.xyy*map( p + k.xyy*h ) + 
               k.yyx*map( p + k.yyx*h ) + 
               k.yxy*map( p + k.yxy*h ) + 
               k.xxx*map( p + k.xxx*h ) );  
    }

    float l = length(p.xz);
    float C = getLaplacian(p);
    color = vec3(
        0.1,
        .1+.2*smoothstep(2., -10., C * l)*.3 * n.y*n.y*n.y,
        0.1
    ) + .3*smoothstep(5., 35., C * l) + smoothstep(-4., -20., C * l)*.1 * n.y*n.y*n.y;

    color *= 5.;
    color *= (max(dot(normalize(vec3(1)), n), 0.)*.75+.25);
    color *= exp(0.-.02*t);

    color *= color * color * color;
    color = tanh(color);
    color = pow(color, vec3(1./2.2));

    fragColor = vec4(color, 1);
}

